import{_ as o,y as l,a as s,o as d,a2 as r,D as n,g as t,I as a}from"./chunks/framework.DCcmcJcL.js";const b=JSON.parse('{"title":"EU Withdrawal","description":"","frontmatter":{},"headers":[],"relativePath":"orders/eu-withdrawal.md","filePath":"orders/eu-withdrawal.md","lastUpdated":1789411722000}'),h={name:"orders/eu-withdrawal.md"};function g(u,e,m,c,w,f){const i=l("ImagePopup");return d(),s("div",null,[e[7]||(e[7]=r('<h1 id="eu-withdrawal" tabindex="-1">EU Withdrawal <a class="header-anchor" href="#eu-withdrawal" aria-label="Permalink to &quot;EU Withdrawal&quot;">​</a></h1><p>The <strong>EU Withdrawal</strong> feature in Bagisto helps store owners comply with <strong>Directive (EU) 2023/2673 (Article 11a CRD)</strong>, the EU Consumer Rights Directive. It gives EU consumers an online way to exercise their statutory 14-day right to withdraw from a distance or off-premises contract.</p><h2 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h2><ul><li><strong>Online Withdrawal Form</strong> — A dedicated page for both logged-in customers and guests to submit a withdrawal declaration.</li><li><strong>Admin Dashboard</strong> — A list of all withdrawals and a detail page with an evidence timeline.</li><li><strong>Durable Medium Confirmation</strong> — A confirmation email sent immediately on submission, which serves as the legally required durable-medium record.</li><li><strong>Guest Withdrawal via Email Link</strong> — Guests withdraw through a temporary signed link sent to their email address.</li><li><strong>Rate Limiting</strong> — Guest lookups and submissions are throttled per IP address to prevent abuse.</li><li><strong>Append-Only Evidence</strong> — A withdrawal record cannot be edited or deleted after it is created.</li><li><strong>One Withdrawal Per Order</strong> — Each order can have at most one withdrawal.</li></ul><h2 id="admin-configuration" tabindex="-1">Admin Configuration <a class="header-anchor" href="#admin-configuration" aria-label="Permalink to &quot;Admin Configuration&quot;">​</a></h2><h3 id="enable-eu-withdrawal" tabindex="-1">Enable EU Withdrawal <a class="header-anchor" href="#enable-eu-withdrawal" aria-label="Permalink to &quot;Enable EU Withdrawal&quot;">​</a></h3><p>The feature is turned on for each channel under <strong>Configure &gt;&gt; Sales &gt;&gt; EU Withdrawals</strong>. See <a href="./../configure/eu-withdrawals.html">EU Withdrawals configuration</a>.</p><blockquote><p><strong>Important:</strong> Only enable the feature on channels selling to EU consumers. When it is disabled for a channel, every withdrawal page, including the public guest lookup, returns a &quot;not found&quot; page, so the feature is invisible to shoppers.</p></blockquote><h2 id="admin-—-managing-withdrawals" tabindex="-1">Admin — Managing Withdrawals <a class="header-anchor" href="#admin-—-managing-withdrawals" aria-label="Permalink to &quot;Admin — Managing Withdrawals&quot;">​</a></h2><h3 id="viewing-all-withdrawals" tabindex="-1">Viewing All Withdrawals <a class="header-anchor" href="#viewing-all-withdrawals" aria-label="Permalink to &quot;Viewing All Withdrawals&quot;">​</a></h3><p>Go to <strong>Sales &gt;&gt; EU Withdrawals</strong>. The grid shows:</p><table tabindex="0"><thead><tr><th>Column</th><th>Description</th></tr></thead><tbody><tr><td><strong>Received At</strong></td><td>Date and time the withdrawal was submitted (sortable, filterable)</td></tr><tr><td><strong>Order ID</strong></td><td>The order number (searchable, linked to the order)</td></tr><tr><td><strong>Customer Email</strong></td><td>Email used at checkout (searchable)</td></tr><tr><td><strong>Status</strong></td><td>Colour-coded: <strong>Received</strong> (yellow), <strong>Refunded</strong> (green), <strong>Declined</strong> (red)</td></tr><tr><td><strong>Channel</strong></td><td>The store channel (filterable)</td></tr><tr><td><strong>Confirmation Sent At</strong></td><td>When the durable-medium confirmation email was sent</td></tr><tr><td><strong>Reference</strong></td><td>The public reference number of the withdrawal (searchable)</td></tr></tbody></table>',12)),n(i,{src:"/images/orders/eu-grid.png",alt:"EU Withdrawal grid"}),e[8]||(e[8]=t("h3",{id:"viewing-withdrawal-details",tabindex:"-1"},[a("Viewing Withdrawal Details "),t("a",{class:"header-anchor",href:"#viewing-withdrawal-details","aria-label":'Permalink to "Viewing Withdrawal Details"'},"​")],-1)),e[9]||(e[9]=t("p",null,[a("Click "),t("strong",null,"View"),a(" on any record to open the detail page. It has two columns.")],-1)),n(i,{src:"/images/orders/eu-view.png",alt:"EU Withdrawal detail view"}),e[10]||(e[10]=r('<p><strong>Evidence card:</strong></p><ul><li><strong>Received At</strong> — The legally effective timestamp (UTC).</li><li><strong>Reference</strong> — The public unique identifier, with a <strong>Copy reference</strong> button.</li><li><strong>Order</strong> — Linked to the order detail page.</li><li><strong>Customer Email</strong> — The email used at checkout.</li><li><strong>Channel</strong> — The store channel.</li><li><strong>Locale</strong> — The language used when submitting.</li><li><strong>Customer&#39;s reason</strong> — The customer&#39;s reason text, if provided.</li></ul><p><strong>Timeline card:</strong></p><ol><li><strong>Declaration Received</strong> — Always marked as done, with the timestamp.</li><li><strong>Initial Confirmation Email</strong> — Shows the sent timestamp (green), pending (grey), or a warning with the error message (red).</li><li><strong>Resolution</strong> — Shows <strong>Withdrawal Declined</strong> (with the reason and the admin who declined it), <strong>Refund Issued</strong> (with the note and the admin who recorded it), or that the withdrawal is awaiting your decision.</li><li><strong>Final Confirmation Email</strong> — Shown only once the withdrawal has been refunded or declined.</li></ol><h3 id="admin-actions" tabindex="-1">Admin Actions <a class="header-anchor" href="#admin-actions" aria-label="Permalink to &quot;Admin Actions&quot;">​</a></h3><p>Three actions are available on the withdrawal detail page. Each one is controlled by an ACL permission, so a user only sees the actions their role allows.</p>',6)),n(i,{src:"/images/orders/eu-actions.png",alt:"EU Withdrawal Actions"}),e[11]||(e[11]=r('<blockquote><p><strong>Note:</strong> The refund itself is processed through the usual order, refund or RMA tools. These actions only record the outcome on the withdrawal evidence.</p></blockquote><h4 id="resending-the-confirmation-email" tabindex="-1">Resending the confirmation email <a class="header-anchor" href="#resending-the-confirmation-email" aria-label="Permalink to &quot;Resending the confirmation email&quot;">​</a></h4><p>Use this when the initial email failed to send, or the customer reports not receiving it.</p><ol><li>On the withdrawal detail page, click <strong>Resend Confirmation Email</strong>.</li><li>Confirm the action.</li></ol><p>If the withdrawal has already been refunded or declined, the email reflects that final status. If sending fails, the error is stored on the timeline.</p><h4 id="marking-a-withdrawal-as-refunded" tabindex="-1">Marking a withdrawal as refunded <a class="header-anchor" href="#marking-a-withdrawal-as-refunded" aria-label="Permalink to &quot;Marking a withdrawal as refunded&quot;">​</a></h4><ol><li>Process the refund through the order as usual.</li><li>On the withdrawal detail page, click <strong>Mark Refunded</strong>.</li><li>Optionally enter a note for the evidence record.</li><li>Confirm the action. The status changes to <strong>Refunded</strong>, and the date and the admin user who recorded it are stored.</li></ol><h4 id="declining-a-withdrawal" tabindex="-1">Declining a withdrawal <a class="header-anchor" href="#declining-a-withdrawal" aria-label="Permalink to &quot;Declining a withdrawal&quot;">​</a></h4><p>Decline a withdrawal when you contest the customer&#39;s entitlement to withdraw.</p><ol><li>On the withdrawal detail page, click <strong>Decline</strong>.</li><li>Enter the <strong>Reason for declining</strong>. This is required and may be up to 500 characters.</li><li>Confirm the action. The status changes to <strong>Declined</strong>, and the date and the admin user who declined it are stored. Any earlier refund record on the withdrawal is cleared.</li></ol><blockquote><p><strong>Important:</strong> Because an order can only have one withdrawal and a declined withdrawal cannot be resubmitted, use this action with care.</p></blockquote><h2 id="customer-—-withdrawing-from-a-contract-logged-in" tabindex="-1">Customer — Withdrawing from a Contract (Logged In) <a class="header-anchor" href="#customer-—-withdrawing-from-a-contract-logged-in" aria-label="Permalink to &quot;Customer — Withdrawing from a Contract (Logged In)&quot;">​</a></h2><h3 id="submitting-the-declaration-from-the-account" tabindex="-1">Submitting the declaration from the account <a class="header-anchor" href="#submitting-the-declaration-from-the-account" aria-label="Permalink to &quot;Submitting the declaration from the account&quot;">​</a></h3>',13)),t("ol",null,[e[2]||(e[2]=r("<li><p>Log in to the customer account and open <strong>Orders</strong>.</p></li><li><p>Click <strong>View</strong> on the order you wish to withdraw from.</p></li><li><p>On the order detail page, click <strong>Withdraw from Contract</strong>. If a withdrawal already exists for this order, the button reads <strong>View your withdrawal</strong> and opens the receipt instead.</p></li>",3)),t("li",null,[e[0]||(e[0]=t("p",null,"Review the withdrawal form.",-1)),n(i,{src:"/images/orders/eu-form.png",alt:"EU Withdrawal Form"}),e[1]||(e[1]=t("ul",null,[t("li",null,[t("strong",null,"This is a legally binding declaration"),a(" — An amber notice explaining that the declaration takes effect the moment the form is submitted.")]),t("li",null,[t("strong",null,"Order"),a(" — The order number, date, total and item count.")]),t("li",null,[t("strong",null,"Reason (optional)"),a(" — A text box in which the customer may explain the reason for withdrawing.")])],-1))]),e[3]||(e[3]=t("li",null,[t("p",null,[a("Click "),t("strong",null,"Submit withdrawal"),a(".")])],-1))]),e[12]||(e[12]=t("h3",{id:"the-receipt-page",tabindex:"-1"},[a("The receipt page "),t("a",{class:"header-anchor",href:"#the-receipt-page","aria-label":'Permalink to "The receipt page"'},"​")],-1)),e[13]||(e[13]=t("p",null,[a("After submitting, the customer is redirected to the "),t("strong",null,"Withdrawal Receipt"),a(" page, which shows:")],-1)),n(i,{src:"/images/orders/eu-receipt.png",alt:"EU Withdrawal Receipt"}),e[14]||(e[14]=r('<ul><li><strong>Status</strong> — <strong>Received</strong> in yellow, or <strong>Refunded</strong> or <strong>Declined</strong> once the merchant has acted.</li><li><strong>Received at</strong> — The legally effective timestamp.</li><li><strong>Reference</strong> — With a <strong>Copy reference</strong> button.</li><li><strong>Order</strong> — With a link back to the order.</li><li><strong>Email</strong> — The email on file.</li><li><strong>Reason</strong> — The reason text, if provided.</li><li><strong>What happens next</strong> — A timeline: declaration received, confirmation email sent, refund issued within 14 days.</li><li>A notice that the page and the confirmation email both serve as confirmation on a durable medium.</li><li><strong>Print</strong> — Opens a print-friendly view.</li></ul><h2 id="guest-withdrawal" tabindex="-1">Guest Withdrawal <a class="header-anchor" href="#guest-withdrawal" aria-label="Permalink to &quot;Guest Withdrawal&quot;">​</a></h2><p>Guests can exercise their right of withdrawal without an account, through a public lookup.</p><h3 id="requesting-the-withdrawal-link" tabindex="-1">Requesting the withdrawal link <a class="header-anchor" href="#requesting-the-withdrawal-link" aria-label="Permalink to &quot;Requesting the withdrawal link&quot;">​</a></h3>',4)),t("ol",null,[e[5]||(e[5]=t("li",null,[t("p",null,[a("On the storefront, open the profile menu in the header and click "),t("strong",null,"Withdraw from a Contract"),a(".")])],-1)),t("li",null,[e[4]||(e[4]=t("p",null,[a("Enter the "),t("strong",null,"Order number"),a(" and the "),t("strong",null,"Email address"),a(" used at checkout.")],-1)),n(i,{src:"/images/orders/eu-guest.png",alt:"EU Withdrawal guest lookup form"})]),e[6]||(e[6]=t("li",null,[t("p",null,[a("Click "),t("strong",null,"Send me the withdrawal link"),a(".")])],-1))]),e[15]||(e[15]=r('<p>The same notice is shown whether or not a matching order exists, so nobody can use the form to discover order numbers. If a matching guest order is found, an email with a temporary signed link, valid for <strong>24 hours</strong>, is queued for sending. If no order matches, no email is sent.</p><h3 id="completing-the-withdrawal" tabindex="-1">Completing the withdrawal <a class="header-anchor" href="#completing-the-withdrawal" aria-label="Permalink to &quot;Completing the withdrawal&quot;">​</a></h3><ol><li><p>Open the email and click the withdrawal link.</p></li><li><p>Review the withdrawal form and optionally enter a <strong>Reason</strong>.</p></li><li><p>Click <strong>Submit withdrawal</strong>.</p></li></ol><p>The confirmation email is sent immediately, and the guest is redirected to the receipt page described above.</p><h2 id="legal-compliance" tabindex="-1">Legal Compliance <a class="header-anchor" href="#legal-compliance" aria-label="Permalink to &quot;Legal Compliance&quot;">​</a></h2><h3 id="durable-medium-requirement-article-11a" tabindex="-1">Durable Medium Requirement (Article 11a) <a class="header-anchor" href="#durable-medium-requirement-article-11a" aria-label="Permalink to &quot;Durable Medium Requirement (Article 11a)&quot;">​</a></h3><p>The confirmation email sent on submission is the <strong>durable medium</strong> required by Article 11a(3) of Directive 2011/83/EU.</p><ul><li><strong>Immediate sending</strong> — The email is sent within the same request, not queued, so a queue failure cannot leave a withdrawal without its legally required confirmation.</li><li><strong>Confirmation timestamp</strong> — The time the confirmation was sent is stored on the withdrawal and shown as <strong>Confirmation Sent At</strong>.</li><li><strong>Final confirmation</strong> — When an admin refunds or declines the withdrawal, the time of that final confirmation email is stored separately, so the original delivery evidence is preserved.</li><li><strong>Email footer</strong> — Each confirmation carries the notice that it is the confirmation on a durable medium required by Article 11a of Directive 2011/83/EU.</li></ul><h2 id="statuses" tabindex="-1">Statuses <a class="header-anchor" href="#statuses" aria-label="Permalink to &quot;Statuses&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>Description</th><th>Final</th></tr></thead><tbody><tr><td><strong>Received</strong></td><td>The withdrawal has been submitted and is awaiting the admin&#39;s decision</td><td>No</td></tr><tr><td><strong>Refunded</strong></td><td>The admin has recorded that the refund was issued</td><td>Yes</td></tr><tr><td><strong>Declined</strong></td><td>The merchant has contested the entitlement to withdraw</td><td>Yes</td></tr></tbody></table><h2 id="email-notifications" tabindex="-1">Email Notifications <a class="header-anchor" href="#email-notifications" aria-label="Permalink to &quot;Email Notifications&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Email</th><th>Sent when</th><th>Delivery</th><th>Content</th></tr></thead><tbody><tr><td><strong>Guest withdrawal link</strong></td><td>A guest lookup matches an order</td><td>Queued</td><td>A temporary signed link valid for 24 hours</td></tr><tr><td><strong>Withdrawal confirmation</strong></td><td>A withdrawal is submitted</td><td>Immediate, not queued</td><td>Reference, received time, order, email, status and durable-medium notice</td></tr><tr><td><strong>Final confirmation</strong></td><td>The admin refunds or declines, or resends the email</td><td>Immediate</td><td>The same details, updated for the final status</td></tr></tbody></table><p>The <strong>Withdrawal confirmation</strong> email is the legal durable-medium record. Its subject names the order, for example &quot;Confirmation of your withdrawal -- Order 123&quot;, and changes wording once the withdrawal has been refunded or declined.</p>',13))])}const T=o(h,[["render",g]]);export{b as __pageData,T as default};
